# Every game owns one cancellable timer; old callbacks cannot restart a reset game.
def game_pause(app):
    app.running = False
    app.generation += 1
    if app.timer is not None:
        app.root.after_cancel(app.timer)
        app.timer = None

def game_tick(app, generation):
    if not app.running or generation != app.generation:
        return
    app.timer = None
    game_step(app)
    game_draw(app)
    if app.running and generation == app.generation:
        app.timer = app.root.after(60, lambda: game_tick(app, generation))

def game_start(app):
    if app.running or app.over:
        return
    app.running = True
    app.generation += 1
    app.Board.focus_set()
    game_tick(app, app.generation)

def game_close(app):
    game_pause(app)
    app.root.destroy()

# Original geometric sprites and a small fixed formation keep the example editable.
def game_reset(app):
    game_pause(app)
    app.player = 300
    app.enemies = [[70 + x * 70, 60 + y * 45] for y in range(3) for x in range(7)]
    app.bullets = []
    app.direction = 1
    app.score = 0
    app.over = False
    game_draw(app)

def invader_move(app, dx):
    if app.running:
        app.player = max(15, min(585, app.player + dx))

def invader_shoot(app):
    if app.running and len(app.bullets) < 5:
        app.bullets.append([app.player, 480])

def game_step(app):
    if any(x < 20 or x > 580 for x, y in app.enemies):
        app.direction *= -1
        for enemy in app.enemies:
            enemy[1] += 18
    for enemy in app.enemies:
        enemy[0] += 3 * app.direction
    remaining = []
    for x, y in app.bullets:
        y -= 14
        hit = next((e for e in app.enemies if abs(e[0]-x) < 19 and abs(e[1]-y) < 17), None)
        if hit is not None:
            app.enemies.remove(hit)
            app.score += 10
        elif y > 0:
            remaining.append([x, y])
    app.bullets = remaining
    app.over = not app.enemies or any(e[1] >= 465 for e in app.enemies)
    if app.over:
        game_pause(app)

def game_draw(app):
    c = app.Board
    c.delete('all')
    for x, y in app.enemies:
        c.create_rectangle(x-17, y-12, x+17, y+12, fill='#58d8a8')
    for x, y in app.bullets:
        c.create_line(x, y, x, y-10, fill='#fff08a', width=3)
    c.create_polygon(app.player, 475, app.player-15, 505, app.player+15, 505, fill='#64b5ff')
    outcome = ('Cleared!' if not app.enemies else 'Game over') if app.over else 'Left/Right and Space'
    app.Status.configure(text=f'Score: {app.score} | {outcome}')
